<script setup>
import {ref,shallowRef,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import * as THREE from 'three'
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import {VRMLoaderPlugin,VRMUtils} from '@pixiv/three-vrm'
import {parseBVH} from './bvh.mjs'
import {buildSourceMotionMaterial,sampleSourceMaterial} from '../motion/source-material.mjs'
import {sourcePoseToSkeleton} from '../motion/material-skeleton.mjs'
import {estimatePlanarAlignment,applyPlanarAlignment} from '../motion/planar-alignment.mjs'
import {buildSourceContactEvidence} from '../motion/source-contact-evidence.mjs'
import {assessMotionSuccessor,rankMotionSuccessors} from '../motion/successor-assessment.mjs'
import {createSourceAnkleTracker} from '../motion/source-ankle-tracker.mjs'
import {createMaterialSequence} from '../motion/material-sequence.mjs'
import {createFootWindowAssessment} from '../motion/foot-window-assessment.mjs'
import {createVRMRotationRetarget} from './rotation-retarget.mjs'
const host=ref(null),material=shallowRef(null),elapsed=ref(0),playing=ref(false),outgoingStart=ref(9),incomingStart=ref(12.6),yaw=ref(0),error=ref(''),status=ref('正在读取本机动作材料与角色…'),ready=ref(false)
const alignmentMode=ref('planar'),cameraMode=ref('fixed'),elevation=ref(18),alignmentReport=shallowRef(null)
const successorReport=shallowRef(null),currentSuccessor=shallowRef(null),ranking=ref(false)
const statusLabel={eligible:'边界条件通过',review:'待接触复核',rejected:'拒绝'}
const worldAlignment=ref('body-basis'),trajectoryMode=ref('off'),trackingNow=shallowRef(null),rigGeometry=shallowRef(null)
const footAssessment=shallowRef(null),assessingFoot=ref(false)
const total=4,transitionStart=1.5,transitionDuration=.5
const rangeError=computed(()=>{if(!material.value)return '';const end=material.value.range.end;if(!Number.isFinite(outgoingStart.value)||outgoingStart.value<0||outgoingStart.value+2>end)return '出段需要覆盖开始时间后的 2 秒。';if(!Number.isFinite(incomingStart.value)||incomingStart.value<0||incomingStart.value+2.5>end)return '入段需要覆盖开始时间后的 2.5 秒。';return ''})
const phase=computed(()=>elapsed.value<1.5?'出段持续运动':elapsed.value<=2?'移动窗口交叉混合':'入段持续运动')
const sourceTimes=computed(()=>`${(outgoingStart.value+elapsed.value).toFixed(3)} / ${(incomingStart.value+Math.max(0,elapsed.value-transitionStart)).toFixed(3)}`)
let renderer,scene,camera,vrm,adapter,plan,observer,ticker,lastNow=0,disposed=false,blobUrl,incomingAlignment,fixedAnchor,contactEvidence,adapterMapping,ankleTracker,adapters
function render(){if(!renderer||!vrm)return;vrm.scene.updateMatrixWorld(true);const hips=vrm.humanoid.getNormalizedBoneNode('hips')||vrm.humanoid.getRawBoneNode('hips'),root=hips?.getWorldPosition(new THREE.Vector3())||new THREE.Vector3(),focus=cameraMode.value==='fixed'&&fixedAnchor?fixedAnchor:root,a=yaw.value*Math.PI/180,pitch=elevation.value*Math.PI/180;camera.position.set(focus.x+Math.sin(a)*4*Math.cos(pitch),.9+4*Math.sin(pitch),focus.z+Math.cos(a)*4*Math.cos(pitch));camera.lookAt(focus.x,.9,focus.z);renderer.render(scene,camera)}
function resize(){if(!renderer||!host.value)return;const {width,height}=host.value.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height);const half=cameraMode.value==='fixed'?2:1.2;camera.left=-half*width/height;camera.right=half*width/height;camera.top=half;camera.bottom=-half;camera.updateProjectionMatrix();render()}
function sourceFeetOf(skeleton){return Object.fromEntries([['left','Foot_L'],['right','Foot_R']].map(([side,name])=>[side,skeleton.positions[material.value.rig.findIndex(j=>j.name===name)].map(v=>v*material.value.metersPerUnit)]))}
function sourceSocketOf(skeleton){const ids=['UpperLeg_L','UpperLeg_R'].map(name=>material.value.rig.findIndex(j=>j.name===name));return skeleton.positions[ids[0]].map((v,i)=>(v+skeleton.positions[ids[1]][i])*.5*material.value.metersPerUnit)}
function targetSocketOf(){return vrm.humanoid.getNormalizedBoneNode('leftUpperLeg').getWorldPosition(new THREE.Vector3()).add(vrm.humanoid.getNormalizedBoneNode('rightUpperLeg').getWorldPosition(new THREE.Vector3())).multiplyScalar(.5).toArray()}
function applyTracked(skeleton){adapter.applyFrame(skeleton);vrm.update(0);const report=trajectoryMode.value==='on'?ankleTracker.apply(sourceFeetOf(skeleton),{sourceSocketMidpoint:sourceSocketOf(skeleton)}):null;if(report)vrm.update(0);return report}
function evaluate(){if(!adapter||!plan||rangeError.value||assessingFoot.value)return;try{trackingNow.value=applyTracked(sourcePoseToSkeleton(material.value,plan.sample(elapsed.value).pose));render()}catch(e){playing.value=false;error.value=e.message}}
function rebuild(){playing.value=false;plan=null;ankleTracker=null;trackingNow.value=null;incomingAlignment=null;alignmentReport.value=null;footAssessment.value=null;if(!material.value||rangeError.value)return;try{const m=material.value;adapter=adapters[worldAlignment.value];adapterMapping={...adapterMapping,sourceMetresToTargetMetres:adapter.scale/m.metersPerUnit,sourceToTargetRotation:adapter.sourceToTargetRotation};successorReport.value=null;currentSuccessor.value=assessMotionSuccessor(m,{outgoingTime:outgoingStart.value+transitionStart,incomingTime:incomingStart.value,duration:transitionDuration,contacts:contactEvidence});plan=createMaterialSequence(m,{outgoingStart:outgoingStart.value,incomingStart:incomingStart.value,total,transitionStart,transitionDuration,align:alignmentMode.value==='planar',contacts:contactEvidence});incomingAlignment=plan.alignment;alignmentReport.value=incomingAlignment;const anchorSkeleton=sourcePoseToSkeleton(m,sampleSourceMaterial(m,m.range.start));adapter.applyFrame(anchorSkeleton);vrm.update(0);const sourceSocket=sourceSocketOf(anchorSkeleton),targetSocket=targetSocketOf(),sourceHip=anchorSkeleton.positions[m.rig.findIndex(j=>j.name==='Hips')].map(v=>v*m.metersPerUnit),targetHip=vrm.humanoid.getNormalizedBoneNode('hips').getWorldPosition(new THREE.Vector3()).toArray();rigGeometry.value={sourcePelvisToSocketMetres:Math.hypot(...sourceHip.map((v,i)=>v-sourceSocket[i])),sourcePelvisToSocketInTargetMetres:Math.hypot(...sourceHip.map((v,i)=>v-sourceSocket[i]))*adapterMapping.sourceMetresToTargetMetres,targetPelvisToSocketMetres:Math.hypot(...targetHip.map((v,i)=>v-targetSocket[i])),rootShiftLimitMetres:.3,anchorLegVectors:{}};for(const [side,name] of [['left','L'],['right','R']]){const footIndex=m.rig.findIndex(j=>j.name==='Foot_'+name),hipIndex=m.rig.findIndex(j=>j.name==='UpperLeg_'+name),sourceVector=new THREE.Vector3(...anchorSkeleton.positions[footIndex]).sub(new THREE.Vector3(...anchorSkeleton.positions[hipIndex])).multiplyScalar(m.metersPerUnit*adapterMapping.sourceMetresToTargetMetres).applyAxisAngle(new THREE.Vector3(0,1,0),adapterMapping.sourceToTargetYaw),targetVector=vrm.humanoid.getNormalizedBoneNode(side+'Foot').getWorldPosition(new THREE.Vector3()).sub(vrm.humanoid.getNormalizedBoneNode(side+'UpperLeg').getWorldPosition(new THREE.Vector3()));rigGeometry.value.anchorLegVectors[side]={angleDifferenceRadians:sourceVector.angleTo(targetVector),sourceMappedLength:sourceVector.length(),targetLength:targetVector.length(),vectorDifferenceMetres:sourceVector.distanceTo(targetVector)}}ankleTracker=createSourceAnkleTracker(vrm,{...adapterMapping,sourceSocketAnchor:sourceSocket,targetSocketAnchor:targetSocket,maxRootShift:.3,sourceAnchor:sourceFeetOf(anchorSkeleton),targetAnchor:Object.fromEntries(['left','right'].map(side=>[side,vrm.humanoid.getNormalizedBoneNode(side+'Foot').getWorldPosition(new THREE.Vector3()).toArray()]))});adapter.applyFrame(sourcePoseToSkeleton(m,plan.sample(0).pose));vrm.update(0);fixedAnchor=vrm.humanoid.getNormalizedBoneNode('hips').getWorldPosition(new THREE.Vector3());error.value='';evaluate()}catch(e){error.value=e.message}}
async function assessFeet(){if(!plan||assessingFoot.value)return;playing.value=false;assessingFoot.value=true;error.value='';const sequence=plan,m=material.value,collector=createFootWindowAssessment(adapterMapping),trackingStats={mode:trajectoryMode.value,worldAlignment:worldAlignment.value,anchorPolicy:'original source first frame and calibrated target first frame',frames:0,projectedCount:0,maxDesiredError:0,maxRotationRewriteRadians:0,maxRootShift:0,rootShiftClampCount:0,rigGeometry:rigGeometry.value};try{for(let i=0;i<=240;i++){if(disposed)throw Error('cancelled');const time=i/60,item=sequence.sample(time),skeleton=sourcePoseToSkeleton(m,item.pose);const track=applyTracked(skeleton);if(track){trackingStats.frames++;trackingStats.maxRootShift=Math.max(trackingStats.maxRootShift,track.rootShiftMagnitude);trackingStats.rootShiftClampCount+=Number(track.rootShiftClamped);trackingStats.projectedCount+=track.projectedCount;trackingStats.maxDesiredError=Math.max(trackingStats.maxDesiredError,track.maxDesiredError);trackingStats.maxRotationRewriteRadians=Math.max(trackingStats.maxRotationRewriteRadians,track.maxRotationRewriteRadians)}const sourceFeet={},targetFeet={};for(const [side,name] of [['left','Foot_L'],['right','Foot_R']]){const index=m.rig.findIndex(j=>j.name===name),bone=vrm.humanoid.getNormalizedBoneNode(side+'Foot');if(index<0||!bone)throw Error('脚部骨骼缺失');sourceFeet[side]={position:skeleton.positions[index].map(v=>v*m.metersPerUnit),rotation:new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().fromArray(skeleton.matrices[index]).transpose()).normalize().toArray(),evidence:item.evidence[side]};targetFeet[side]={position:bone.getWorldPosition(new THREE.Vector3()).toArray(),rotation:bone.getWorldQuaternion(new THREE.Quaternion()).toArray()};}collector.push({time,sourceFeet,targetFeet,phase:item.phase});if(i%30===0)await new Promise(requestAnimationFrame)}footAssessment.value={...collector.finish(),ankleTracking:trackingStats,plan:{outgoingStart:outgoingStart.value,incomingStart:incomingStart.value,alignmentMode:alignmentMode.value,worldAlignment:worldAlignment.value},targetObservation:'normalized VRM foot bones after humanoid update; not mesh soles',soleOffsets:'unknown'}}catch(e){if(!disposed)error.value=e.message}finally{assessingFoot.value=false;if(!disposed)evaluate()}}
async function rankSuccessors(){if(!material.value||ranking.value||assessingFoot.value||rangeError.value)return;playing.value=false;ranking.value=true;error.value='';await new Promise(requestAnimationFrame);try{const candidates=[];for(let t=9;t<=material.value.range.end-2.5;t+=.5)if(Math.abs(t-(outgoingStart.value+transitionStart))>.75)candidates.push({id:`source-${t.toFixed(1)}`,time:t});successorReport.value=rankMotionSuccessors(material.value,{outgoingTime:outgoingStart.value+transitionStart,candidates,duration:transitionDuration,contacts:contactEvidence})}catch(e){error.value=e.message}finally{ranking.value=false}}
function previewSuccessor(row){if(assessingFoot.value)return;incomingStart.value=row.time;elapsed.value=0}
function seek(value){playing.value=false;elapsed.value=Math.max(0,Math.min(total,Number(value)));evaluate()}
function tick(now){const dt=lastNow?Math.min((now-lastNow)/1000,.1):0;lastNow=now;if(playing.value&&ready.value&&!rangeError.value){elapsed.value=Math.min(total,elapsed.value+dt);evaluate();if(elapsed.value>=total)playing.value=false}ticker=requestAnimationFrame(tick)}
function play(){if(elapsed.value>=total)elapsed.value=0;playing.value=!playing.value;evaluate()}
watch([outgoingStart,incomingStart,alignmentMode,trajectoryMode,worldAlignment],rebuild);watch([yaw,elevation],render);watch(cameraMode,resize)
onMounted(async()=>{ticker=requestAnimationFrame(tick);try{const [avatar,reference]=await Promise.all([window.komorebi.motionAvatar(),window.komorebi.motionReference()]);if(disposed)return;if(!avatar?.bytes||!reference?.text)throw Error('本机研究角色或 BVH 参考不可用。');const bvh=parseBVH(reference.text);material.value=buildSourceMotionMaterial(bvh,{metersPerUnit:.01,sourceId:'local-bvh-research',provenance:{license:'CC BY-NC 4.0',unitAssumption:'research: 0.01 metre per source unit'}});contactEvidence=buildSourceContactEvidence(material.value);if(disposed)return;renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(devicePixelRatio);renderer.outputColorSpace=THREE.SRGBColorSpace;host.value.append(renderer.domElement);scene=new THREE.Scene();camera=new THREE.OrthographicCamera(-1,1,1.2,-1.2,.1,30);scene.add(new THREE.HemisphereLight(0xffffff,0xabb5c5,2));const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(1,3,3);scene.add(light);scene.add(new THREE.GridHelper(12,48,0xcbd4dd,0xe0e6ed));blobUrl=URL.createObjectURL(new Blob([avatar.bytes],{type:'model/gltf-binary'}));const loader=new GLTFLoader();loader.register(parser=>new VRMLoaderPlugin(parser));const gltf=await loader.loadAsync(blobUrl);URL.revokeObjectURL(blobUrl);blobUrl=null;vrm=gltf.userData.vrm;if(!vrm)throw Error('角色没有 VRM 人体骨架。');if(disposed){VRMUtils.deepDispose(vrm.scene);return}VRMUtils.rotateVRM0(vrm);scene.add(vrm.scene);vrm.scene.updateMatrixWorld(true);const first=sourcePoseToSkeleton(material.value,sampleSourceMaterial(material.value,0)),li=material.value.rig.findIndex(j=>j.name==='UpperLeg_L'),ri=material.value.rig.findIndex(j=>j.name==='UpperLeg_R'),sourceRight=new THREE.Vector3(...first.positions[li]).sub(new THREE.Vector3(...first.positions[ri])),targetRight=vrm.humanoid.getNormalizedBoneNode('leftUpperLeg').getWorldPosition(new THREE.Vector3()).sub(vrm.humanoid.getNormalizedBoneNode('rightUpperLeg').getWorldPosition(new THREE.Vector3()));const mappingYaw=Math.atan2(-targetRight.z,targetRight.x)-Math.atan2(-sourceRight.z,sourceRight.x);adapters={'body-basis':createVRMRotationRetarget(vrm,bvh,{rootMode:'source',worldAlignment:'body-basis'}),'y-up':createVRMRotationRetarget(vrm,bvh,{rootMode:'source',worldAlignment:'y-up'})};adapter=adapters[worldAlignment.value];adapterMapping={sourceToTargetYaw:mappingYaw,sourceMetresToTargetMetres:adapter.scale/material.value.metersPerUnit,sourceToTargetRotation:adapter.sourceToTargetRotation};ready.value=true;status.value='';observer=new ResizeObserver(resize);observer.observe(host.value);rebuild();resize()}catch(e){if(!disposed){error.value=e.message;status.value=''}}})
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(ticker);observer?.disconnect();adapter?.dispose?.();if(blobUrl)URL.revokeObjectURL(blobUrl);if(scene)VRMUtils.deepDispose(scene);renderer?.dispose();renderer?.domElement.remove()})
</script>
<template>
 <div class="material-study">
  <p v-if="status" role="status">{{status}}</p><p v-if="error||rangeError" class="study-error" role="alert">{{error||rangeError}}</p>
  <div class="material-layout">
   <section class="material-preview"><div class="preview-label">完整 VRM · 源动作材料 → 移动窗口 → 旋转映射</div><div ref="host" class="material-canvas" aria-label="材料移动过渡 VRM 预览"/><div class="angle"><label>机位 <select v-model="cameraMode" aria-label="材料观察机位"><option value="fixed">固定地面</option><option value="follow">跟随角色</option></select></label><label>俯角 <input v-model.number="elevation" aria-label="材料观察俯角" type="range" min="0" max="45"/></label></div><label class="angle">观察角度 <input v-model.number="yaw" type="range" min="-180" max="180"/></label></section>
   <section class="material-detail"><h2>在运动中交接。</h2><p>先把每一帧存为源骨架材料，再让出段和入段在同一个 0.5 秒窗口里继续采样。局部旋转用四元数插值，位置用五次平滑权重混合，最后重建骨架并映射到角色。</p>
    <div class="material-settings"><label>空间对齐<select v-model="alignmentMode" aria-label="材料空间对齐" :disabled="!ready||assessingFoot"><option value="planar">水平位置与朝向</option><option value="none">未对齐 · 对照</option></select></label><label>出段起点 / 秒<input v-model.number="outgoingStart" type="number" min="0" step=".1" :disabled="!ready||assessingFoot"/></label><label>入段起点 / 秒<input v-model.number="incomingStart" type="number" min="0" step=".1" :disabled="!ready||assessingFoot"/></label></div>
    <section class="successor-panel"><h3>下一段先看兼容性</h3><p v-if="currentSuccessor">当前候选：{{statusLabel[currentSuccessor.status]}} · {{currentSuccessor.reasons.join('；')||'只通过边界检查'}}</p><button :disabled="!ready||ranking||assessingFoot||!!rangeError" aria-label="评估动作后继" @click="rankSuccessors">{{ranking?'正在评估…':'检索候选后继'}}</button><p>接触由踝部运动估计，未人工标注。待复核候选只供研究预览，不自动用于日常舞蹈；边界通过也不代表完整过渡可执行。</p><ol v-if="successorReport"><li v-for="row in successorReport.slice(0,5)" :key="row.id">{{row.time.toFixed(2)}}秒 · {{statusLabel[row.status]}} · {{row.reasons.join('；')}} <button v-if="row.status!=='rejected'" @click="previewSuccessor(row)">研究预览</button></li></ol></section><section class="successor-panel"><h3>完整窗口 · 脚部归因</h3><label>身体世界坐标 <select v-model="worldAlignment" aria-label="身体世界坐标对齐" :disabled="!ready||assessingFoot"><option value="body-basis">身体基对齐 · 原基线</option><option value="y-up">Y轴向上 · 保留重力方向</option></select></label><label>踝轨迹跟随（源首帧标定） <select v-model="trajectoryMode" aria-label="源踝轨迹跟随" :disabled="!ready||assessingFoot"><option value="off">关闭 · 旋转基线</option><option value="on">开启 · 源踝与髋关节中心适配</option></select></label><p v-if="trackingNow">髋关节中心适配位移 {{(trackingNow.rootShiftMagnitude*100).toFixed(2)}} 厘米 · 当前期望目标残差 {{(trackingNow.maxDesiredError*100).toFixed(2)}} 厘米 · 可达域投影 {{trackingNow.projectedCount}} 脚 · 最大旋转改写 {{(trackingNow.maxRotationRewriteRadians*180/Math.PI).toFixed(1)}}°。</p><button aria-label="评估完整脚部窗口" :disabled="!ready||assessingFoot||ranking||!!rangeError" @click="assessFeet">{{assessingFoot?'评估中…':'评估源脚与目标脚'}}</button><p>比较各脚相对窗口起点的踝部位移；不是脚底接触或穿地判定。过渡内接触保持未知，未启用锁脚。</p><details v-if="footAssessment"><summary>查看脚部聚合结果</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px">{{JSON.stringify(footAssessment,null,2)}}</pre></details></section><p class="phase" role="status">{{phase}} · {{elapsed.toFixed(3)}} / 4.000 秒</p><p>过渡位于 1.500–2.000 秒。源时钟（出 / 入）：{{sourceTimes}} 秒。</p>
    <dl><dt>材料单位</dt><dd>显式研究假设：1 源单位 = 0.01 米；未根据身高自动推测。</dd><dt>接触与音乐</dt><dd>足接触未知；未推断接触、未做音乐对齐。</dd><dt>根轨迹</dt><dd>{{alignmentMode==='planar'?'交接起点对齐髋部水平位置与朝向；固定变换持续用于整段入段，保留高度差。':'保留两段原始场景位置，可能发生明显横移。'}}</dd><dt>约束与物理</dt><dd>{{trajectoryMode==='on'?'先适配源髋关节中心轨迹，再以双骨腿IK跟随源踝轨迹；目标超出带余量可达域时显式投影并保留原目标残差。不做接触锁脚或头发衣物物理。':'未启用足锁、IK或头发衣物物理。'}}平滑插值不代表自然度验证。</dd></dl>
    <p v-if="alignmentReport" class="material-proof">对齐变换：yaw {{(alignmentReport.yaw*180/Math.PI).toFixed(2)}}° · XZ平移 {{alignmentReport.translation[0].toFixed(3)}} / {{alignmentReport.translation[2].toFixed(3)}} 米 · Y平移 0。起点水平间隔 {{alignmentReport.diagnostics.beforePlanarSeparation.toFixed(3)}} → {{alignmentReport.diagnostics.afterPlanarSeparation.toFixed(6)}} 米。起点匹配不等于足接触或舞蹈兼容。</p><p v-if="material" class="material-proof">源材料 {{material.frames.length}} 帧 · 可采样 0–{{material.range.end.toFixed(3)}} 秒 · 本次加载只构建一次。</p>
    <p class="reference-license">来源：本机 BVH 舞蹈参考（CC BY-NC 4.0），本机 VRM 角色 © Jessair。角色和材料仅在内存中使用，不上传或自动导出；原始资产不随源码或应用包提供。</p>
   </section>
  </div>
  <footer class="study-transport"><button :disabled="!ready||assessingFoot||!!rangeError||!!error" @click="play">{{playing?'暂停':'播放'}}</button><button :disabled="!ready||assessingFoot" @click="seek(0)">回到起点</button><span class="study-time">{{elapsed.toFixed(3)}} / 4.000s</span><input type="range" min="0" max="4" step=".001" :value="elapsed" :disabled="!ready||assessingFoot||!!rangeError" aria-label="材料过渡时间轴" @input="seek($event.target.value)"/></footer>
 </div>
</template>
<style scoped>
.material-study{display:flex;flex:1;min-height:0;flex-direction:column}.material-layout{display:grid;grid-template-columns:minmax(330px,1.2fr) minmax(280px,1fr);flex:1;min-height:0;overflow:hidden;grid-template-rows:minmax(0,1fr);gap:24px}.material-preview{position:relative;display:flex;flex-direction:column;min-height:0;background:#f1f5f8;border-radius:12px;overflow:hidden}.material-canvas{flex:1;min-height:0}.material-canvas :deep(canvas){display:block;width:100%;height:100%}.preview-label{padding:16px;font-size:11px;color:#617689}.angle{padding:12px 20px;font-size:11px;display:flex;align-items:center;gap:14px}.material-detail{min-height:0;overflow:auto;padding:12px 18px 20px 0;font-size:12px;line-height:1.8;color:#5b7187}.material-detail h2{font-size:23px;line-height:1.4;color:#354d63;margin:0 0 16px}.material-settings{display:flex;gap:16px;margin:20px 0}.material-settings label{display:grid;gap:5px}.material-settings input{width:100px;background:white;border:1px solid #d5dfe9;border-radius:6px;padding:6px 8px;color:#435e76}.phase{font-weight:600;color:#395d71;padding:10px 12px;background:#e8f0f4;border-radius:6px}.material-detail dl{display:grid;grid-template-columns:74px 1fr;gap:10px;margin:20px 0}.material-detail dt{color:#3d586d}.material-detail dd{margin:0}.material-proof,.reference-license{font-size:10px;color:#718497}.successor-panel{border-top:1px solid #d5dfe9;padding:12px 0;margin-top:14px}.successor-panel h3{margin:0 0 8px}.successor-panel ol{padding-left:20px}.successor-panel li{margin:8px 0}.successor-panel button{font-size:11px;padding:5px 9px;border:1px solid #ccd8e0;background:#fff;border-radius:5px;color:#435e76}.material-study button:disabled{opacity:.45}@media(max-width:850px){.material-layout{grid-template-columns:1fr;grid-template-rows:auto auto;overflow:auto}.material-preview{min-height:420px}.material-detail{overflow:visible;padding:12px 18px}}
</style>
